/* ---- SDP (RFC 4566) + WebRTC 用法 (RFC 8829 / 8839 / 8841) ------------------
   SDP 是一叠 <单字符>=<值> 的行，顺序敏感：
     v= 版本，o= 源，s= 会话名，t= 时间 —— 会话级
     m= 之后的所有行都属于那一条媒体，直到下一条 m=
   WebRTC 把它当成协商载体：ICE 凭证、DTLS 指纹、编解码器、BUNDLE 分组、
   方向（sendrecv/sendonly/recvonly/inactive）全塞在 a= 属性里。
---------------------------------------------------------------------------- */

var DIRECTIONS = {sendrecv:1, sendonly:1, recvonly:1, inactive:1};

var CANDIDATE_TYPES = {
  host:  '本机地址：网卡上直接看得到的地址，同网段直连最快',
  srflx: '服务端自反：STUN 服务器回报的公网映射地址，NAT 打洞用',
  prflx: '对端自反：连通性检查过程中，从对方来包里现学到的地址',
  relay: '中继：TURN 服务器转发，最后的保底路径，费流量也最慢'
};

function splitSdpLines(text){
  var s = String(text==null?'':text);
  if(s.charCodeAt(0)===0xFEFF) s = s.slice(1);
  var raw = s.split(/\r\n|\r|\n/), out=[];
  for(var i=0;i<raw.length;i++){ if(raw[i]!=='') out.push(raw[i]); }
  return out;
}

function parseLine(line){
  var l = String(line);
  if(l.charAt(1) !== '=' || l.length < 2) return {type:'?', value:l, malformed:true};
  return {type:l.charAt(0), value:l.slice(2), malformed:false};
}

function parseAttribute(value){
  var v = String(value), c = v.indexOf(':');
  if(c < 0) return {name:v, value:null, flag:true};
  return {name:v.slice(0,c), value:v.slice(c+1), flag:false};
}

function parseOrigin(v){
  var p = String(v==null?'':v).split(/\s+/);
  return {username:p[0]||'', sessionId:p[1]||'', sessionVersion:p[2]||'',
          netType:p[3]||'', addrType:p[4]||'', address:p[5]||'', ok:p.length>=6};
}

function parseMediaLine(v){
  var p = String(v==null?'':v).split(/\s+/);
  var portField = String(p[1]||''), slash = portField.split('/');
  return {kind:p[0]||'', port:parseInt(slash[0],10),
          portCount: slash.length>1 ? parseInt(slash[1],10) : 1,
          proto:p[2]||'', fmts:p.slice(3), ok:p.length>=4};
}

function parseConnection(v){
  var p = String(v==null?'':v).split(/\s+/);
  return {netType:p[0]||'', addrType:p[1]||'', address:p[2]||'', ok:p.length>=3};
}

function parseFingerprint(v){
  var p = String(v==null?'':v).split(/\s+/);
  var hash = (p[0]||'').toLowerCase(), val = p[1]||'';
  var parts = val ? val.split(':') : [];
  var want = {'sha-1':20,'sha-224':28,'sha-256':32,'sha-384':48,'sha-512':64}[hash] || 0;
  var bad = false;
  for(var i=0;i<parts.length;i++){ if(!/^[0-9a-fA-F]{2}$/.test(parts[i])) bad = true; }
  return {hash:hash, value:val, bytes:parts.length, expected:want,
          ok: !!hash && !!val && !bad && (want===0 || parts.length===want)};
}

function ipKind(addr){
  var a = String(addr==null?'':addr).trim();
  if(!a) return {family:'', kind:'unknown', label:'空地址'};
  if(/\.local$/i.test(a)) return {family:'mdns', kind:'mdns', label:'mDNS 主机名（浏览器已做地址隐藏）'};
  if(a.indexOf(':') >= 0){
    var low = a.toLowerCase();
    if(low === '::' ) return {family:'IPv6', kind:'any', label:'通配地址（占位）'};
    if(low === '::1') return {family:'IPv6', kind:'loopback', label:'环回地址'};
    if(/^fe[89ab]/.test(low)) return {family:'IPv6', kind:'linklocal', label:'链路本地地址，跨网段不可达'};
    if(/^f[cd]/.test(low)) return {family:'IPv6', kind:'private', label:'唯一本地地址（ULA），内网'};
    return {family:'IPv6', kind:'public', label:'公网 IPv6'};
  }
  if(!/^\d{1,3}(\.\d{1,3}){3}$/.test(a)) return {family:'', kind:'name', label:'主机名，不是字面地址'};
  var o = a.split('.').map(function(x){ return parseInt(x,10); });
  for(var j=0;j<4;j++){ if(!(o[j]>=0 && o[j]<=255)) return {family:'IPv4', kind:'invalid', label:'非法 IPv4'}; }
  if(a === '0.0.0.0') return {family:'IPv4', kind:'any', label:'通配地址（占位，真实地址在 candidate 里）'};
  if(o[0]===127) return {family:'IPv4', kind:'loopback', label:'环回地址'};
  if(o[0]===10) return {family:'IPv4', kind:'private', label:'内网地址 10/8'};
  if(o[0]===172 && o[1]>=16 && o[1]<=31) return {family:'IPv4', kind:'private', label:'内网地址 172.16/12'};
  if(o[0]===192 && o[1]===168) return {family:'IPv4', kind:'private', label:'内网地址 192.168/16'};
  if(o[0]===169 && o[1]===254) return {family:'IPv4', kind:'linklocal', label:'链路本地地址 169.254/16'};
  if(o[0]===100 && o[1]>=64 && o[1]<=127) return {family:'IPv4', kind:'cgnat', label:'运营商级 NAT 段 100.64/10'};
  return {family:'IPv4', kind:'public', label:'公网 IPv4'};
}

/* ---- ICE 候选 ------------------------------------------------------------
   a=candidate:<foundation> <component> <transport> <priority> <ip> <port>
               typ <type> [raddr <ip> rport <port>] [tcptype ...] [generation ...]
---------------------------------------------------------------------------- */
function parseCandidate(str){
  var s = String(str==null?'':str).trim();
  s = s.replace(/^a=/, '').replace(/^candidate:/, '').trim();
  if(!s) return {ok:false, error:'空候选串'};
  var p = s.split(/\s+/);
  if(p.length < 8) return {ok:false, error:'候选至少要有 8 段，当前 '+p.length+' 段', raw:s};
  var c = {raw:s, foundation:p[0], component:parseInt(p[1],10), transport:p[2],
           priority:parseInt(p[3],10), address:p[4], port:parseInt(p[5],10),
           type:'', relatedAddress:'', relatedPort:null, tcptype:'', generation:null,
           ufrag:'', networkId:null, networkCost:null, extras:{}, ok:true, error:''};
  if(p[6] !== 'typ'){ c.ok=false; c.error='第 7 段必须是关键字 typ，实际是 "'+p[6]+'"'; }
  else c.type = p[7]||'';
  for(var i=8;i+1<p.length;i+=2){
    var k=p[i], v=p[i+1];
    if(k==='raddr') c.relatedAddress=v;
    else if(k==='rport') c.relatedPort=parseInt(v,10);
    else if(k==='tcptype') c.tcptype=v;
    else if(k==='generation') c.generation=parseInt(v,10);
    else if(k==='ufrag') c.ufrag=v;
    else if(k==='network-id') c.networkId=parseInt(v,10);
    else if(k==='network-cost') c.networkCost=parseInt(v,10);
    else c.extras[k]=v;
  }
  c.componentName = c.component===1?'RTP' : c.component===2?'RTCP' : ('component '+c.component);
  c.typeLabel = CANDIDATE_TYPES[c.type] || '未知类型';
  c.addressKind = ipKind(c.address);
  if(!(c.priority>=0)){ c.ok=false; c.error=c.error||'优先级不是数字'; }
  if(!(c.port>=0 && c.port<=65535)){ c.ok=false; c.error=c.error||'端口越界'; }
  if(c.transport && !/^(udp|tcp|ssltcp)$/i.test(c.transport)){ c.ok=false; c.error=c.error||'未知传输层 "'+c.transport+'"'; }
  if((c.type==='srflx'||c.type==='relay'||c.type==='prflx') && !c.relatedAddress){
    c.warn = '非 host 候选按 RFC 8839 应带 raddr/rport';
  }
  return c;
}

/* priority = 2^24 * 类型优先 + 2^8 * 本地优先 + (256 - 组件号)   —— RFC 8445 */
function decodePriority(p){
  var n = Number(p);
  if(!isFinite(n) || n < 0 || Math.floor(n) !== n) return {ok:false, error:'优先级必须是非负整数'};
  if(n > 2147483647) return {ok:false, error:'优先级超出 31 位取值范围'};
  var typePref  = Math.floor(n / 16777216);
  var localPref = Math.floor(n / 256) % 65536;
  var comp      = 256 - (n % 256);
  var guess = typePref===126 ? 'host' : typePref===110 ? 'prflx'
            : typePref===100 ? 'srflx' : typePref===0 ? 'relay' : '自定义';
  return {ok:true, priority:n, typePreference:typePref, localPreference:localPref,
          componentId:comp, likelyType:guess,
          note: guess==='自定义' ? '类型优先值不在浏览器默认表（126/110/100/0）里' : ''};
}

function buildPriority(typePref, localPref, component){
  var t=Number(typePref), l=Number(localPref), c=Number(component);
  if(!(t>=0 && t<=126)) return {ok:false, error:'类型优先值应在 0–126'};
  if(!(l>=0 && l<=65535)) return {ok:false, error:'本地优先值应在 0–65535'};
  if(!(c>=1 && c<=256)) return {ok:false, error:'组件号应在 1–256'};
  return {ok:true, priority: 16777216*Math.floor(t) + 256*Math.floor(l) + (256-Math.floor(c))};
}

/* 一对候选的配对优先级 —— RFC 8445 第 6.1.2.3 节 */
function pairPriority(controllingPriority, controlledPriority){
  var G=Number(controllingPriority), D=Number(controlledPriority);
  if(!isFinite(G) || !isFinite(D)) return {ok:false, error:'两个优先级都得是数字'};
  var lo = Math.min(G,D), hi = Math.max(G,D);
  var v = 4294967296*lo + 2*hi + (G>D?1:0);
  return {ok:true, value:v, min:lo, max:hi,
          exact: v <= 9007199254740991,
          note: v > 9007199254740991 ? '配对优先级是 64 位整数，超出 JS 双精度安全范围，这里的低位仅供参考' : ''};
}

function newSection(){
  return {kind:'', line:'', m:null, connection:null, attrs:[], direction:null, mid:null,
          ice:{ufrag:'', pwd:'', options:'', lite:false}, dtls:{fingerprints:[], setup:''},
          candidates:[], endOfCandidates:false, rtcpMux:false, rtcpRsize:false,
          rtpmap:{}, fmtp:{}, rtcpFb:{}, extmaps:[], ssrcs:{}, ssrcGroups:[],
          rids:[], simulcast:'', msid:'', bandwidth:[], rejected:false, raw:[]};
}

function absorbAttribute(target, at, isSession){
  var n = at.name, v = at.value;
  if(DIRECTIONS[n]){ target.direction = target.direction ? target.direction : n;
                     target.directionCount = (target.directionCount||0)+1; return; }
  if(n==='mid'){ target.mid = v; return; }
  if(n==='ice-ufrag'){ target.ice.ufrag = v||''; return; }
  if(n==='ice-pwd'){ target.ice.pwd = v||''; return; }
  if(n==='ice-options'){ target.ice.options = v||''; return; }
  if(n==='ice-lite'){ target.ice.lite = true; return; }
  if(n==='fingerprint'){ target.dtls.fingerprints.push(parseFingerprint(v)); return; }
  if(n==='setup'){ target.dtls.setup = v||''; return; }
  if(isSession) return;
  if(n==='candidate'){ target.candidates.push(parseCandidate(v)); return; }
  if(n==='end-of-candidates'){ target.endOfCandidates = true; return; }
  if(n==='rtcp-mux'){ target.rtcpMux = true; return; }
  if(n==='rtcp-rsize'){ target.rtcpRsize = true; return; }
  if(n==='msid'){ target.msid = v||''; return; }
  if(n==='rtpmap'){
    var rp = String(v||'').split(/\s+/), pt = rp[0], body = (rp[1]||'').split('/');
    target.rtpmap[pt] = {payload:pt, name:body[0]||'',
                         clockRate: body[1]?parseInt(body[1],10):null,
                         channels: body[2]?parseInt(body[2],10):null};
    return;
  }
  if(n==='fmtp'){
    var fp = String(v||''), sp = fp.indexOf(' ');
    if(sp>0) target.fmtp[fp.slice(0,sp)] = fp.slice(sp+1);
    return;
  }
  if(n==='rtcp-fb'){
    var fb = String(v||'').split(/\s+/), fpt = fb[0];
    if(!target.rtcpFb[fpt]) target.rtcpFb[fpt] = [];
    target.rtcpFb[fpt].push(fb.slice(1).join(' '));
    return;
  }
  if(n==='extmap'){
    var em = String(v||''), s2 = em.indexOf(' ');
    var idPart = s2>0 ? em.slice(0,s2) : em, uri = s2>0 ? em.slice(s2+1) : '';
    var dirSplit = idPart.split('/');
    target.extmaps.push({id: parseInt(dirSplit[0],10), direction: dirSplit[1]||'', uri: uri});
    return;
  }
  if(n==='ssrc'){
    var ss = String(v||''), sp2 = ss.indexOf(' ');
    var id = sp2>0 ? ss.slice(0,sp2) : ss, rest = sp2>0 ? ss.slice(sp2+1) : '';
    if(!target.ssrcs[id]) target.ssrcs[id] = {};
    var colon = rest.indexOf(':');
    if(colon>0) target.ssrcs[id][rest.slice(0,colon)] = rest.slice(colon+1);
    else if(rest) target.ssrcs[id][rest] = true;
    return;
  }
  if(n==='ssrc-group'){ target.ssrcGroups.push(v||''); return; }
  if(n==='rid'){ target.rids.push(v||''); return; }
  if(n==='simulcast'){ target.simulcast = v||''; return; }
}

function parseSdp(text){
  var lines = splitSdpLines(text);
  var doc = {version:null, origin:null, sessionName:null, info:null, timing:[],
             connection:null, attrs:[], media:[], malformed:[], lineCount:lines.length,
             ice:{ufrag:'', pwd:'', options:'', lite:false}, dtls:{fingerprints:[], setup:''},
             groups:[], bundle:[], msidSemantic:'', direction:null, raw:lines};
  var cur = null;
  for(var i=0;i<lines.length;i++){
    var pl = parseLine(lines[i]);
    if(pl.malformed){ doc.malformed.push({index:i, line:lines[i], reason:'不是 <字符>=<值> 形式'}); continue; }
    if(pl.type === 'm'){
      cur = newSection();
      cur.index = doc.media.length; cur.line = pl.value; cur.m = parseMediaLine(pl.value);
      cur.kind = cur.m.kind; cur.rejected = (cur.m.port === 0);
      cur.raw.push(lines[i]); doc.media.push(cur); continue;
    }
    if(cur) cur.raw.push(lines[i]);
    var tgt = cur || doc;
    switch(pl.type){
      case 'v': doc.version = pl.value; break;
      case 'o': doc.origin = parseOrigin(pl.value); break;
      case 's': doc.sessionName = pl.value; break;
      case 'i': if(cur) cur.info = pl.value; else doc.info = pl.value; break;
      case 't': doc.timing.push(pl.value); break;
      case 'b': tgt.bandwidth = (tgt.bandwidth||[]).concat([pl.value]); break;
      case 'c': tgt.connection = parseConnection(pl.value); break;
      case 'a':
        var at = parseAttribute(pl.value);
        tgt.attrs.push(at);
        if(!cur){
          if(at.name==='group'){
            doc.groups.push(at.value||'');
            var g = String(at.value||'').split(/\s+/);
            if((g[0]||'').toUpperCase()==='BUNDLE') doc.bundle = g.slice(1);
          } else if(at.name==='msid-semantic'){ doc.msidSemantic = at.value||''; }
        }
        absorbAttribute(tgt, at, !cur);
        break;
      default: break;
    }
  }
  for(var k=0;k<doc.media.length;k++) doc.media[k].codecs = collectCodecs(doc.media[k]);
  return doc;
}

function collectCodecs(section){
  var out = [], fmts = (section.m && section.m.fmts) || [];
  var isRtp = /RTP\/(S)?AVPF?/i.test((section.m && section.m.proto) || '');
  for(var i=0;i<fmts.length;i++){
    var pt = fmts[i], rm = section.rtpmap[pt];
    out.push({payload: pt, name: rm ? rm.name : (isRtp ? '' : pt),
              clockRate: rm ? rm.clockRate : null, channels: rm ? rm.channels : null,
              fmtp: section.fmtp[pt] || '', feedback: section.rtcpFb[pt] || [],
              known: !!rm});
  }
  return out;
}

function summarize(doc){
  var s = {mediaCount: doc.media.length, kinds: [], bundle: doc.bundle.slice(),
           mids: [], candidates: 0, byType: {}, byComponent: {}, codecs: 0,
           dtlsSetup: doc.dtls.setup, iceUfrag: doc.ice.ufrag, trickle: false,
           rejected: 0, addresses: {}};
  var opts = (doc.ice.options||'');
  for(var i=0;i<doc.media.length;i++){
    var m = doc.media[i];
    s.kinds.push(m.kind); if(m.mid!=null) s.mids.push(m.mid);
    if(m.rejected) s.rejected++;
    s.codecs += m.codecs ? m.codecs.length : 0;
    if(!s.dtlsSetup && m.dtls.setup) s.dtlsSetup = m.dtls.setup;
    if(!s.iceUfrag && m.ice.ufrag) s.iceUfrag = m.ice.ufrag;
    if(!opts && m.ice.options) opts = m.ice.options;
    for(var j=0;j<m.candidates.length;j++){
      var c = m.candidates[j];
      s.candidates++;
      s.byType[c.type||'?'] = (s.byType[c.type||'?']||0)+1;
      s.byComponent[c.componentName||'?'] = (s.byComponent[c.componentName||'?']||0)+1;
      var kind = c.addressKind ? c.addressKind.kind : 'unknown';
      s.addresses[kind] = (s.addresses[kind]||0)+1;
    }
  }
  s.trickle = /\btrickle\b/.test(opts);
  s.iceOptions = opts;
  return s;
}

function lint(text){
  var doc = (typeof text === 'string') ? parseSdp(text) : text;
  var out = [];
  function add(level, msg, where){ out.push({level:level, message:msg, where:where||''}); }

  if(doc.version === null) add('error','缺少 v= 行，SDP 必须以 v=0 开头');
  else if(doc.version !== '0') add('warn','v= 应当是 0，当前是 "'+doc.version+'"');
  if(!doc.origin || !doc.origin.ok) add('error','o= 行缺失或字段不足 6 段');
  if(doc.sessionName === null) add('error','缺少 s= 行（WebRTC 惯例写 s=-）');
  if(!doc.timing.length) add('error','缺少 t= 行（WebRTC 惯例写 t=0 0）');
  for(var q=0;q<doc.malformed.length;q++) add('error','第 '+(doc.malformed[q].index+1)+' 行不合法：'+doc.malformed[q].line);
  if(!doc.media.length) add('error','没有任何 m= 媒体行，这份 SDP 协商不出东西');

  var midSet = {};
  for(var i=0;i<doc.media.length;i++){
    var m = doc.media[i], at = 'm='+m.kind+' #'+(i+1);
    if(!m.m.ok) add('error','m= 行字段不足 4 段', at);
    if(m.rejected){ add('info','端口为 0，这条媒体已被拒绝/关闭', at); }
    if(m.mid == null){ if(doc.bundle.length) add('error','参与 BUNDLE 却没有 a=mid，无法归组', at); }
    else { if(midSet[m.mid]) add('error','mid "'+m.mid+'" 重复', at); midSet[m.mid]=1; }
    if(!m.direction && !doc.direction) add('warn','没有方向属性，对端只能按 sendrecv 兜底', at);
    if((m.directionCount||0) > 1) add('error','出现了 '+m.directionCount+' 个方向属性，只能有一个', at);
    if(m.rejected) continue;

    var ufrag = m.ice.ufrag || doc.ice.ufrag, pwd = m.ice.pwd || doc.ice.pwd;
    if(!ufrag) add('error','缺少 a=ice-ufrag，ICE 无法开始', at);
    else if(ufrag.length < 4 || ufrag.length > 256) add('warn','ice-ufrag 长度应在 4–256，当前 '+ufrag.length, at);
    if(!pwd) add('error','缺少 a=ice-pwd，ICE 无法开始', at);
    else if(pwd.length < 22 || pwd.length > 256) add('warn','ice-pwd 长度应在 22–256，当前 '+pwd.length, at);

    var fps = m.dtls.fingerprints.length ? m.dtls.fingerprints : doc.dtls.fingerprints;
    if(!fps.length) add('error','缺少 a=fingerprint，DTLS-SRTP 起不来', at);
    else for(var f=0;f<fps.length;f++){
      if(!fps[f].ok) add('error','fingerprint 格式不对（'+fps[f].hash+' 期望 '+fps[f].expected+' 字节，实得 '+fps[f].bytes+'）', at);
      else if(fps[f].hash === 'sha-1') add('warn','fingerprint 用了 sha-1，建议 sha-256', at);
    }
    var setup = m.dtls.setup || doc.dtls.setup;
    if(!setup) add('error','缺少 a=setup，DTLS 角色未定', at);
    else if(!/^(active|passive|actpass|holdconn)$/.test(setup)) add('error','a=setup 取值非法："'+setup+'"', at);

    if(/RTP\//i.test(m.m.proto)){
      if(!m.rtcpMux) add('warn','没有 a=rtcp-mux，会多占一条 ICE 组件（现代浏览器一律要求复用）', at);
      var ptSeen = {};
      for(var c2=0;c2<m.codecs.length;c2++){
        var cd = m.codecs[c2];
        if(!cd.known) add('error','载荷类型 '+cd.payload+' 出现在 m= 行却没有对应 a=rtpmap', at);
        if(ptSeen[cd.payload]) add('error','载荷类型 '+cd.payload+' 在 m= 行里重复', at);
        ptSeen[cd.payload]=1;
      }
      for(var pt in m.rtpmap){ if(!ptSeen[pt]) add('warn','a=rtpmap 定义了 '+pt+'（'+m.rtpmap[pt].name+'）但 m= 行没列出来，对端会忽略', at); }
      if(!m.codecs.length) add('error','m= 行没有列出任何载荷类型', at);
    }
    var extSeen = {};
    for(var e=0;e<m.extmaps.length;e++){
      var id = m.extmaps[e].id;
      if(extSeen[id]) add('error','extmap 编号 '+id+' 重复', at);
      extSeen[id]=1;
      if(!(id>=1 && id<=14) && !(id>=15 && id<=255)) add('warn','extmap 编号 '+id+' 越界', at);
    }
    if(!m.connection) add('warn','这条媒体既没有 c= 行，会话级也要有一条兜底', at);

    var haveRtcpComp = false, mdns = 0, publicIp = 0;
    for(var k=0;k<m.candidates.length;k++){
      var cc = m.candidates[k];
      if(!cc.ok) add('error','候选解析失败：'+cc.error, at);
      if(cc.component === 2) haveRtcpComp = true;
      if(cc.addressKind && cc.addressKind.kind==='mdns') mdns++;
      if(cc.addressKind && cc.addressKind.kind==='public') publicIp++;
      if(cc.warn) add('info', cc.warn+'（'+cc.foundation+'）', at);
    }
    if(haveRtcpComp && m.rtcpMux) add('warn','已经 rtcp-mux 了还带 component 2 的候选，属于冗余', at);
    if(mdns) add('info','有 '+mdns+' 条 mDNS（.local）候选，这是浏览器的本机地址隐藏机制', at);
    if(publicIp) add('info','有 '+publicIp+' 条候选暴露了公网地址，分享日志前记得脱敏', at);
  }
  for(var b=0;b<doc.bundle.length;b++){
    if(!midSet[doc.bundle[b]]) add('error','BUNDLE 组引用了不存在的 mid "'+doc.bundle[b]+'"');
  }
  if(doc.media.length > 1 && !doc.bundle.length) add('info','多条媒体但没有 a=group:BUNDLE，会各开一套 ICE，握手更慢');
  return out;
}

/* ---- offer / answer 核对 —— RFC 8829 第 5.10 节的常见踩坑点 ------------- */
var ANSWER_OK = {
  sendrecv: {sendrecv:1, sendonly:1, recvonly:1, inactive:1},
  sendonly: {recvonly:1, inactive:1},
  recvonly: {sendonly:1, inactive:1},
  inactive: {inactive:1}
};

function negotiate(offerText, answerText){
  var o = (typeof offerText === 'string') ? parseSdp(offerText) : offerText;
  var a = (typeof answerText === 'string') ? parseSdp(answerText) : answerText;
  var issues = [], perMedia = [];
  function add(level, msg, where){ issues.push({level:level, message:msg, where:where||''}); }

  if(o.media.length !== a.media.length){
    add('error','m= 行数量必须一致：offer '+o.media.length+' 条，answer '+a.media.length+' 条');
  }
  var n = Math.min(o.media.length, a.media.length);
  for(var i=0;i<n;i++){
    var om = o.media[i], am = a.media[i], at = '第 '+(i+1)+' 条媒体';
    var row = {index:i, kind:om.kind, answerKind:am.kind, mid:om.mid, ok:true, notes:[]};
    var bad = (function(where, r){ return function(level, msg){
      add(level, msg, where); if(level==='error'){ r.ok=false; } r.notes.push(msg);
    }; })(at, row);

    if(om.kind !== am.kind) bad('error','媒体类型对不上：offer 是 '+om.kind+'，answer 是 '+am.kind+'（m= 行顺序必须原样保持）');
    if(String(om.mid) !== String(am.mid)) bad('error','mid 对不上：offer "'+om.mid+'" vs answer "'+am.mid+'"');
    if(om.m.proto !== am.m.proto) bad('error','传输协议对不上：'+om.m.proto+' vs '+am.m.proto);

    var od = om.direction || 'sendrecv', ad = am.direction || 'sendrecv';
    row.offerDirection = od; row.answerDirection = ad;
    if(am.rejected){
      row.notes.push('answer 把这条媒体拒了（端口 0）');
      perMedia.push(row); continue;
    }
    if(om.rejected && !am.rejected) bad('error','offer 已经拒了这条媒体，answer 必须同样置端口 0');
    if(ANSWER_OK[od] && !ANSWER_OK[od][ad]){
      bad('error','方向不互补：offer 是 '+od+'，answer 不能回 '+ad+'（应当是 '+Object.keys(ANSWER_OK[od]).join(' / ')+'）');
    }

    var os = om.dtls.setup || o.dtls.setup, as = am.dtls.setup || a.dtls.setup;
    row.offerSetup = os; row.answerSetup = as;
    if(os === 'actpass'){
      if(as !== 'active' && as !== 'passive') bad('error','offer 给的是 actpass，answer 必须明确选 active 或 passive，当前是 "'+as+'"');
    } else if(os === 'active' && as !== 'passive'){
      bad('error','offer 是 active，answer 只能是 passive');
    } else if(os === 'passive' && as !== 'active'){
      bad('error','offer 是 passive，answer 只能是 active');
    }

    var offerPts = {}, k;
    for(k=0;k<om.codecs.length;k++) offerPts[om.codecs[k].payload] = om.codecs[k];
    var common = [];
    for(k=0;k<am.codecs.length;k++){
      var c = am.codecs[k];
      if(!offerPts[c.payload]){
        bad('error','answer 选了 offer 里没有的载荷类型 '+c.payload+(c.name?('（'+c.name+'）'):''));
      } else {
        var oc = offerPts[c.payload];
        if(c.name && oc.name && c.name.toLowerCase() !== oc.name.toLowerCase()){
          bad('error','载荷类型 '+c.payload+' 两边名字不同：'+oc.name+' vs '+c.name+'（同一个 PT 必须指同一个编解码器）');
        }
        if(c.clockRate && oc.clockRate && c.clockRate !== oc.clockRate){
          bad('error','载荷类型 '+c.payload+' 采样率不同：'+oc.clockRate+' vs '+c.clockRate);
        }
        common.push(c.payload + (c.name?(' '+c.name):''));
      }
    }
    row.commonCodecs = common;
    if(!common.length && /RTP\//i.test(am.m.proto)) bad('error','没有任何共同编解码器，这条流协商不出来');

    if(!(am.ice.ufrag || a.ice.ufrag)) bad('error','answer 缺 ice-ufrag');
    if(!(am.ice.pwd || a.ice.pwd)) bad('error','answer 缺 ice-pwd');
    if(om.rtcpMux && !am.rtcpMux) bad('warn','offer 要求 rtcp-mux，answer 没回应，会退化成两条组件');
    perMedia.push(row);
  }
  var ob = o.bundle.join(' '), ab = a.bundle.join(' ');
  if(ob && !ab) add('warn','offer 提了 BUNDLE，answer 没有 a=group:BUNDLE，会各开一套 ICE');
  else if(ob && ab && ab.split(' ').length > ob.split(' ').length) add('error','answer 的 BUNDLE 组不能比 offer 的更大');

  var errors = 0, warns = 0;
  for(var z=0;z<issues.length;z++){ if(issues[z].level==='error') errors++; else if(issues[z].level==='warn') warns++; }
  return {ok: errors===0, errors:errors, warnings:warns, issues:issues, media:perMedia};
}

/* ---- 脱敏：把 SDP 贴进工单/issue 之前先过一遍 --------------------------- */
function maskAddress(addr){
  var a = String(addr==null?'':addr);
  if(!a) return a;
  if(/\.local$/i.test(a)) return a;
  if(a.indexOf(':') >= 0){
    var seg = a.split(':');
    for(var i=2;i<seg.length;i++){ if(seg[i]!=='') seg[i]='xxxx'; }
    return seg.join(':');
  }
  var o = a.split('.');
  if(o.length === 4){ o[2]='x'; o[3]='x'; return o.join('.'); }
  return 'x.x.x.x';
}

function redact(text, opts){
  var cfg = opts || {};
  var doCreds = cfg.creds !== false, doIp = cfg.ip !== false;
  var doFp = cfg.fingerprint !== false, doIds = cfg.ids !== false;
  var lines = String(text==null?'':text).split(/\r\n|\r|\n/), out = [];
  for(var i=0;i<lines.length;i++){
    var l = lines[i];
    if(doCreds && /^a=ice-pwd:/.test(l)) { out.push('a=ice-pwd:' + new Array((l.length-10>0?l.length-10:8)+1).join('x')); continue; }
    if(doCreds && /^a=ice-ufrag:/.test(l)){ out.push('a=ice-ufrag:xxxx'); continue; }
    if(doFp && /^a=fingerprint:/.test(l)){
      var fp = parseFingerprint(l.slice(14));
      var bytes = fp.bytes || 32, parts = [];
      for(var b=0;b<bytes;b++) parts.push('XX');
      out.push('a=fingerprint:' + (fp.hash||'sha-256') + ' ' + parts.join(':'));
      continue;
    }
    if(doIp && /^o=/.test(l)){
      var og = parseOrigin(l.slice(2));
      if(og.ok){ out.push('o=' + [og.username, doIds?'0':og.sessionId, og.sessionVersion, og.netType, og.addrType, maskAddress(og.address)].join(' ')); continue; }
    }
    if(doIp && /^c=/.test(l)){
      var cn = parseConnection(l.slice(2));
      if(cn.ok){ out.push('c=' + [cn.netType, cn.addrType, maskAddress(cn.address)].join(' ')); continue; }
    }
    if(doIp && /^a=candidate:/.test(l)){
      var c = parseCandidate(l);
      if(c.ok !== false || c.foundation){
        var p = l.replace(/^a=candidate:/,'').split(/\s+/);
        if(p.length >= 6) p[4] = maskAddress(p[4]);
        for(var j=8;j+1<p.length;j+=2){ if(p[j]==='raddr') p[j+1] = maskAddress(p[j+1]); }
        out.push('a=candidate:' + p.join(' '));
        continue;
      }
    }
    if(doIds && /^a=ssrc:/.test(l)){
      out.push(l.replace(/(cname:)\S+/, '$1REDACTED').replace(/(msid:)\S+(\s+\S+)?/, '$1REDACTED REDACTED')
                .replace(/(label:)\S+/, '$1REDACTED').replace(/(mslabel:)\S+/, '$1REDACTED'));
      continue;
    }
    if(doIds && /^a=msid:/.test(l)){ out.push('a=msid:REDACTED REDACTED'); continue; }
    out.push(l);
  }
  return out.join('\n');
}

function stats(doc){
  var d = (typeof doc === 'string') ? parseSdp(doc) : doc;
  var s = summarize(d);
  return {'媒体条数': String(d.media.length),
          '媒体类型': s.kinds.join(' / ') || '-',
          'BUNDLE 组': s.bundle.length ? s.bundle.join(' ') : '未分组',
          '候选总数': String(s.candidates),
          '编解码器条目': String(s.codecs),
          'DTLS 角色': s.dtlsSetup || '-',
          'Trickle ICE': s.trickle ? '开启' : '未声明',
          '被拒媒体': String(s.rejected),
          '总行数': String(d.lineCount)};
}

function toJson(doc){
  var d = (typeof doc === 'string') ? parseSdp(doc) : doc;
  var media = [];
  for(var i=0;i<d.media.length;i++){
    var m = d.media[i];
    media.push({kind:m.kind, port:m.m.port, proto:m.m.proto, mid:m.mid,
                direction:m.direction, rtcpMux:m.rtcpMux, rejected:m.rejected,
                setup:m.dtls.setup, iceUfrag:m.ice.ufrag,
                codecs:(m.codecs||[]).map(function(c){ return {pt:c.payload, name:c.name, clockRate:c.clockRate, channels:c.channels, fmtp:c.fmtp, feedback:c.feedback}; }),
                candidates:(m.candidates||[]).map(function(c){ return {type:c.type, transport:c.transport, address:c.address, port:c.port, priority:c.priority, component:c.component}; })});
  }
  return {version:d.version, origin:d.origin, sessionName:d.sessionName,
          bundle:d.bundle, iceOptions:d.ice.options, media:media};
}

